def can_connect_districts(n, gangs):
    gang_count = defaultdict(int)
    for g in gangs:
        gang_count[g] += 1

    if len(gang_count) < 2:
        return False, None

    min_gang, max_gang = min(gang_count.keys()), max(gang_count.keys())
    graph = [[] for _ in range(n + 1)]

    # Connect districts within the same gang
    for i in range(1, n + 1):
        if gangs[i - 1] == min_gang:
            graph[min_gang].append(i)
            graph[i].append(min_gang)
        elif gangs[i - 1] == max_gang:
            graph[max_gang].append(i)
            graph[i].append(max_gang)

    # Check if the graph is connected
    visited = [False] * (n + 1)
    queue = deque([min_gang])
    while queue:
        node = queue.popleft()
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                queue.append(neighbor)

    return all(visited[1:]) and min_gang != max_gang, [(min_gang, max_gang)] * (n - 1)

