                for j in range(i + 1, n):
                    if gangs[i] != gangs[j] and j + 1 in adj_list[i + 1]:
                        edges.append((i + 1, j + 1))
            for edge in edges[:n - 1]:
                results.append(f"{edge[0]} {edge[1]}")
        else:
            results.append("NO")

    for result in results:
        print(result)

